func faceRollDegrees(_ cg: CGImage) -> Double? {
    var result: Double?
    let req = VNDetectFaceLandmarksRequest { request, _ in
        guard let faces = request.results as? [VNFaceObservation], let face = faces.first else { return }
        // roll: radians, positive = counterclockwise in Vision coords sometimes
        if let roll = face.roll?.doubleValue {
            result = roll * 180.0 / .pi
        }
    }
    let handler = VNImageRequestHandler(cgImage: cg, options: [:])
    try? handler.perform([req])
    return result
}

func rotate(_ cg: CGImage, degrees: Double) -> CGImage? {
    let radians = degrees * .pi / 180.0
    let w = CGFloat(cg.width)
    let h = CGFloat(cg.height)
    let transform = CGAffineTransform(translationX: w/2, y: h/2)
        .rotated(by: CGFloat(radians))
        .translatedBy(x: -w/2, y: -h/2)
    let corners = [
        CGPoint(x: 0, y: 0), CGPoint(x: w, y: 0),
        CGPoint(x: 0, y: h), CGPoint(x: w, y: h)
    ].map { $0.applying(transform) }
    let minX = corners.map(\.x).min()!
    let maxX = corners.map(\.x).max()!
    let minY = corners.map(\.y).min()!
    let maxY = corners.map(\.y).max()!
    let newW = Int(ceil(maxX - minX))
    let newH = Int(ceil(maxY - minY))
    let colorSpace = cg.colorSpace ?? CGColorSpaceCreateDeviceRGB()
    guard let ctx = CGContext(
        data: nil, width: newW, height: newH,
        bitsPerComponent: cg.bitsPerComponent, bytesPerRow: 0,
        space: colorSpace,
        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
    ) else { return nil }
    // fill red background close to original
    ctx.setFillColor(red: 0.72, green: 0.06, blue: 0.04, alpha: 1)
    ctx.fill(CGRect(x: 0, y: 0, width: newW, height: newH))
    ctx.translateBy(x: CGFloat(newW)/2, y: CGFloat(newH)/2)
    ctx.rotate(by: CGFloat(radians))
    ctx.translateBy(x: -w/2, y: -h/2)
    ctx.draw(cg, in: CGRect(x: 0, y: 0, width: w, height: h))
    return ctx.makeImage()
}

func cropCenterPortrait(_ cg: CGImage, aspect: CGFloat = 3.0/4.0) -> CGImage? {
    let w = CGFloat(cg.width)
    let h = CGFloat(cg.height)
    var cropW = w
    var cropH = cropW / aspect
    if cropH > h {
        cropH = h
        cropW = cropH * aspect
    }
    let x = (w - cropW) / 2
    let y = (h - cropH) / 2
    return cg.cropping(to: CGRect(x: x, y: y, width: cropW, height: cropH))
}

