import Foundation
import AppKit
import Vision
import ImageIO
import CoreGraphics

func loadCGImage(_ path: String) -> CGImage? {
    let url = URL(fileURLWithPath: path)
    guard let src = CGImageSourceCreateWithURL(url as CFURL, nil) else { return nil }
    return CGImageSourceCreateImageAtIndex(src, 0, nil)
}

func saveJPEG(_ image: CGImage, path: String) {
    let url = URL(fileURLWithPath: path)
    guard let dest = CGImageDestinationCreateWithURL(url as CFURL, "public.jpeg" as CFString, 1, nil) else { return }
    let opts: [CFString: Any] = [kCGImageDestinationLossyCompressionQuality: 0.95]
    CGImageDestinationAddImage(dest, image, opts as CFDictionary)
    CGImageDestinationFinalize(dest)
}

struct EyeAngle {
    let degrees: Double
    let leftEye: CGPoint
    let rightEye: CGPoint
}

func eyeLineAngle(_ cg: CGImage) -> EyeAngle? {
    var out: EyeAngle?
    let req = VNDetectFaceLandmarksRequest { request, _ in
        guard let faces = request.results as? [VNFaceObservation],
              let face = faces.max(by: { ($0.boundingBox.width*$0.boundingBox.height) < ($1.boundingBox.width*$1.boundingBox.height) }),
              let landmarks = face.landmarks,
              let left = landmarks.leftEye,
              let right = landmarks.rightEye else { return }
        // landmark points are normalized in face bounding box
        let bb = face.boundingBox
        func toImage(_ p: CGPoint) -> CGPoint {
            let nx = bb.origin.x + p.x * bb.width
            let ny = bb.origin.y + p.y * bb.height
            // Vision: origin bottom-left; convert to top-left image coords for angle
            let x = nx * CGFloat(cg.width)
            let y = (1 - ny) * CGFloat(cg.height)
            return CGPoint(x: x, y: y)
        }
        // average eye points
        func avg(_ region: VNFaceLandmarkRegion2D) -> CGPoint {
            let pts = (0..<region.pointCount).map { toImage(region.normalizedPoints[$0]) }
            let sx = pts.reduce(0) { $0 + $1.x }
            let sy = pts.reduce(0) { $0 + $1.y }
            return CGPoint(x: sx / CGFloat(pts.count), y: sy / CGFloat(pts.count))
        }
        let le = avg(left)
        let re = avg(right)
        // angle of line left->right eye; positive means right eye lower (clockwise tilt of head visually)
        let dy = re.y - le.y
        let dx = re.x - le.x
        let deg = atan2(Double(dy), Double(dx)) * 180.0 / .pi
        out = EyeAngle(degrees: deg, leftEye: le, rightEye: re)
    }
    let handler = VNImageRequestHandler(cgImage: cg, options: [:])
    try? handler.perform([req])
    return out
}

func rotate(_ cg: CGImage, degrees: Double, fillRed: Bool = true) -> CGImage? {
    let radians = degrees * .pi / 180.0
    let w = CGFloat(cg.width)
    let h = CGFloat(cg.height)
    let transform = CGAffineTransform(translationX: w/2, y: h/2)
        .rotated(by: CGFloat(radians))
        .translatedBy(x: -w/2, y: -h/2)
    let corners = [
        CGPoint(x: 0, y: 0), CGPoint(x: w, y: 0),
        CGPoint(x: 0, y: h), CGPoint(x: w, y: h)
    ].map { $0.applying(transform) }
    let minX = corners.map(\.x).min()!
    let maxX = corners.map(\.x).max()!
    let minY = corners.map(\.y).min()!
    let maxY = corners.map(\.y).max()!
    let newW = Int(ceil(maxX - minX))
    let newH = Int(ceil(maxY - minY))
    let colorSpace = CGColorSpaceCreateDeviceRGB()
    guard let ctx = CGContext(
        data: nil, width: newW, height: newH,
        bitsPerComponent: 8, bytesPerRow: 0,
        space: colorSpace,
        bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
    ) else { return nil }
    if fillRed {
        ctx.setFillColor(red: 0.72, green: 0.06, blue: 0.04, alpha: 1)
        ctx.fill(CGRect(x: 0, y: 0, width: newW, height: newH))
    }
    ctx.translateBy(x: CGFloat(newW)/2, y: CGFloat(newH)/2)
    ctx.rotate(by: CGFloat(radians))
    ctx.translateBy(x: -w/2, y: -h/2)
    ctx.draw(cg, in: CGRect(x: 0, y: 0, width: w, height: h))
    return ctx.makeImage()
}

func cropCenterPortrait(_ cg: CGImage, aspect: CGFloat = 3.0/4.0, scale: CGFloat = 0.92) -> CGImage? {
    let w = CGFloat(cg.width)
    let h = CGFloat(cg.height)
    var cropW = w * scale
    var cropH = cropW / aspect
    if cropH > h * scale {
        cropH = h * scale
        cropW = cropH * aspect
    }
    let x = (w - cropW) / 2
    let y = (h - cropH) / 2
    return cg.cropping(to: CGRect(x: x, y: y, width: cropW, height: cropH))
}

let args = CommandLine.arguments
guard args.count >= 3 else {
    fputs("usage: straighten2 <in> <out> [manual_deg]\n", stderr)
    exit(1)
}
let inPath = args[1]
let outPath = args[2]
let manual: Double? = args.count >= 4 ? Double(args[3]) : nil
guard let cg = loadCGImage(inPath) else {
    fputs("load fail\n", stderr)
